+++ b/test/ai.check.js
@@ -0,0 +1,23 @@
+const assert = require('assert');
+const fs = require('fs');
+const path = require('path');
+let captured;
+globalThis.fetch = async (url, init) => {
+  captured = { body: JSON.parse(init.body), headers: new Headers(init.headers) };
+  return new Response(JSON.stringify({
+    id: 'msg_1', type: 'message', role: 'assistant', model: 'x',
+    content: [{ type: 'text', text: 'Привет' }, { type: 'text', text: '!' }],
+    stop_reason: 'end_turn', stop_sequence: null, usage: { input_tokens: 1, output_tokens: 1 },
+  }), { status: 200, headers: { 'content-type': 'application/json' } });
+};
+process.env.ANTHROPIC_API_KEY = 'dummy';
+const { askJasmin } = require('../ai.js');
+(async () => {
+  const text = await askJasmin('hi', [{ role: 'assistant', content: 'yo' }]);
+  assert.strictEqual(text, 'Привет!');
+  for (const k of ['temperature', 'top_p', 'top_k']) assert(!(k in captured.body));
+  assert.strictEqual(captured.headers.get('anthropic-version'), '2026-10-21');
+  const v = JSON.parse(fs.readFileSync(path.join(__dirname, '../node_modules/@anthropic-ai/sdk/package.json'), 'utf8')).version;
+  assert(v.startsWith('1.'), v);
+  console.log('ok');
+})().catch(e => { console.error(e); process.exit(1); });
